engine.stripOoxmlNoise:
function stripOoxmlNoise(xml) {
  if (!xml) return "";
  var s = String(xml);
  // Strip rsid attributes (revision-session ids — Word writes a fresh
  // one on every keystroke; meaningless for diff).
  s = s.replace(/\s+w:rsid[A-Za-z]*="[^"]*"/g, "");
  // Strip date attributes on track-change tags (we don't render dates).
  s = s.replace(/\s+w:date="[^"]*"/g, "");
  // Strip w:id attributes on paragraphs / runs (Word regenerates them).
  s = s.replace(/\s+w:id="[^"]*"/g, "");
  // Collapse whitespace runs in attributes.
  s = s.replace(/\s{2,}/g, " ");
  return s;
}

// ─── Image strip — drop base64 image blobs from snapshots ────────────
// HTML branch — replace <img src="data:image/...> with a placeholder.
// OOXML branch — replace <w:binData> blocks. FROM v2 line 22399.

engine.stripImagesFromSnapshot:
function stripImagesFromSnapshot(html, ooxml) {
  var cleanHtml = String(html || "");
  cleanHtml = cleanHtml.replace(
    /<img[^>]*src=["']data:image\/[^;]+;base64,[^"']+["'][^>]*>/gi,
    "[Image Removed]"
  );
  var cleanOoxml = String(ooxml || "");
  cleanOoxml = cleanOoxml.replace(
    /<w:binData[\s\S]*?<\/w:binData>/g,
    "<w:binData>[Image Removed]</w:binData>"
  );
  return { html: cleanHtml, ooxml: cleanOoxml };
}

// ─── History prune — keep only the most recent N entries ─────────────
// FROM v2 saveHistoryToDoc line 22451. v2 trimmed to 3 inside save AND
// to 5 inside createSnapshot. We use 5 here as the upper cap.

engine.pruneHistory:
function pruneHistory(history, max) {
  var cap = Number(max) || 5;
  if (!Array.isArray(history)) return [];
  var sorted = history.slice().sort(function (a, b) {
    return (a.timestamp || 0) - (b.timestamp || 0);
  });
  if (sorted.length > cap) sorted = sorted.slice(sorted.length - cap);
  return sorted;
}

// ─── Build a snapshot row from raw HTML + OOXML ──────────────────────
// FROM v2 createSnapshot lines 22404-22416. Caller (init) does the
// Word.run; this assembles the entry shape including deterministic
// blocks for compare-friendly diffs.
//
// Self-contained: kernel's evalBundle wraps each engine fn in
// `new Function(...)` so sibling references (stripImagesFromSnapshot,
// stripOoxmlNoise, extractDeterministicBlocks) WOULD throw
// "not defined" at call time. We inline the helpers here.

engine.buildSnapshotEntry:
function buildSnapshotEntry(opts) {
  var html = String(opts.html || "");
  var ooxml = String(opts.ooxml || "");
  // Inline image strip (HTML branch + OOXML branch).
  var cleanHtml = html.replace(
    /<img[^>]*src=["']data:image\/[^;]+;base64,[^"']+["'][^>]*>/gi,
    "[Image Removed]"
  );
  var cleanOoxml = ooxml.replace(
    /<w:binData[\s\S]*?<\/w:binData>/g,
    "<w:binData>[Image Removed]</w:binData>"
  );
  // 2026-05-17: aligned with v2 `_tpStripOoxmlNoise` (taskpane_v2.js:8846).
  // Was: stripped rsid/date/id THEN collapsed `\s{2,}` to single space. The
  // whitespace collapse was destructive — it could corrupt XML structure
  // between elements and broke redline-aware compare on some docs. v2 used
  // SINGLE `\s` prefix (not `\s+`) and never collapsed runs. Aligning here
  // restores v2 compare behavior exactly. Also adds the w16du:dateUtc +
  // w14:textId strips v2 had that v3 was missing.
  cleanOoxml = cleanOoxml
    .replace(/\sw:id="[^"]*"/g, "")
    .replace(/\sw:date="[^"]*"/g, "")
    .replace(/\sw16du:dateUtc="[^"]*"/g, "")
    .replace(/\sw14:textId="[^"]*"/g, "")
    .replace(/\sw:rsid[A-Za-z]*="[^"]*"/g, "");
  // Inline deterministic-block extraction (text-only paragraph cap).
  var blocks = [];
  if (cleanHtml && typeof DOMParser !== "undefined") {
    try {
      var doc = new DOMParser().parseFromString(cleanHtml, "text/html");
      var nodes = doc.querySelectorAll("p, h1, h2, h3, h4, li, blockquote, td, th");
      for (var i = 0; i < nodes.length && blocks.length < 300; i++) {
        var t = (nodes[i].textContent || "").replace(/\s+/g, " ").trim();
        if (t.length > 5) blocks.push({ t: t.substring(0, 800) });
      }
    } catch (e) { /* tolerate */ }
  }
  return {
    sessionId: opts.sessionId || ("sess_" + Date.now()),
    timestamp: opts.timestamp || Date.now(),
    label: opts.label || "Snapshot",
    author: opts.author || "Me",
    html: cleanHtml,
    bodyOoxml: cleanOoxml,
    deterministicBlocks: blocks,
  };
}

// ─── Deterministic-block extraction ──────────────────────────────────
// FROM v2 extractDeterministicBlocksFromHtml (line 17603) — text-only
// blocks that survive across Word/Office HTML normalization, used by
// future Compare tool for stable cross-version diffs. Capped at 300
// blocks × 800 chars to keep snapshot under ~250KB.

engine.extractDeterministicBlocks:
function extractDeterministicBlocks(html) {
  if (!html) return [];
  if (typeof DOMParser === "undefined") return [];
  var doc;
  try { doc = new DOMParser().parseFromString(html, "text/html"); }
  catch (e) { return []; }
  var blocks = [];
  var nodes = doc.querySelectorAll("p, h1, h2, h3, h4, li, blockquote, td, th");
  for (var i = 0; i < nodes.length && blocks.length < 300; i++) {
    var t = (nodes[i].textContent || "").replace(/\s+/g, " ").trim();
    if (t.length > 5) blocks.push({ t: t.substring(0, 800) });
  }
  return blocks;
}

// ─── Format display label ────────────────────────────────────────────
// FROM v2 line 22593. "Auto-Save" + optional suffix.

engine.formatLabel:
function formatLabel(suffix) {
  var base = "Auto-Save";
  if (suffix && suffix.length) base += " (" + String(suffix) + ")";
  return base;
}

// ─── Format timestamp for timeline display ───────────────────────────

engine.formatTs:
function formatTs(ts) {
  if (!ts) return "—";
  try { return new Date(Number(ts)).toLocaleString(); }
  catch (e) { return String(ts); }
}

// ─── Engine entry — convenience wrapper for caller orchestration ─────
// Self-contained: pruneHistory is INLINED here because evalBundle
// isolates each engine fn — sibling references throw "not defined"
// at call time. Caused "version_history_open_failed: pruneHistory is
// not defined" when the timeline tried to open.

engine.analyze:
function analyze(input, providers) {
  var history = Array.isArray(input.history) ? input.history : [];
  var cap = 5;
  var sorted = Array.isArray(history) ? history.slice().sort(function (a, b) {
    return (a.timestamp || 0) - (b.timestamp || 0);
  }) : [];
  if (sorted.length > cap) sorted = sorted.slice(sorted.length - cap);
  // Clone each entry before adding displayNumber — pure functions don't
  // mutate inputs. The init layer's _writeHistory used to strip
  // displayNumber before persist; cloning here makes that strip
  // unnecessary and prevents accidental persistence of UI state.
  var withNums = [];
  for (var i = 0; i < sorted.length; i++) {
    var clone = {};
    Object.keys(sorted[i]).forEach(function (k) { clone[k] = sorted[i][k]; });
    clone.displayNumber = i + 1;
    withNums.push(clone);
  }
  return Promise.resolve({
    history: withNums,
    overview: withNums.length + " version" + (withNums.length === 1 ? "" : "s") + " saved",
    provenance: {
      kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
      toolVersion: "v3.0",
      docHash: input.docHash || null,
      timestamp: Date.now(),
    },
  });
}

view.renderTimeline:
function renderTimeline(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var versions = (opts.versions || []).slice();
  var currentSessionId = opts.currentSessionId || "";
  var onDelete = opts.onDelete || function () {};
  var onView = opts.onView || function () {};
  var onCompare = opts.onCompare || function () {};
  var onBack = opts.onBack || function () {};
  var formatTs = opts.formatTs || function (t) {
    try { return new Date(Number(t)).toLocaleString(); } catch (e) { return String(t); }
  };

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // Sort newest-first for display, but keep a copy of the 1-based
  // displayNumber that engine assigned (oldest = #1).
  versions.sort(function (a, b) { return (b.timestamp || 0) - (a.timestamp || 0); });

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_ae_root _eli3_vh_root";
  // Capture button moved to the kernel footer (next to the version
  // pill) — no longer rendered here. Footer camera click goes through
  // window.eli.versionHistory.createSnapshot which persists to the
  // document. Snapshots live with the document forever (5-cap pruning).
  root.innerHTML =
    '<div class="_eli3_ae_bar">' +
      '<button class="_eli3_ae_back" title="Back">←</button>' +
      '<div class="_eli3_ae_title">📷 Version History</div>' +
    '</div>' +
    '<div class="_eli3_vh_intro">' +
      '<strong>Version History</strong> · Snapshots are stored on the document and travel with it. ' +
      'Use the 📷 button in the footer to capture a new snapshot. 5-version cap; oldest auto-pruned.' +
    '</div>' +
    '<div class="_eli3_vh_list" id="_eli3_vh_list"></div>';

  root.querySelector("._eli3_ae_back").onclick = onBack;

  var listEl = root.querySelector("#_eli3_vh_list");
  if (!versions.length) {
    listEl.innerHTML =
      '<div class="_eli3_vh_empty">' +
        '<div class="_eli3_vh_empty_icon">📷</div>' +
        '<div class="_eli3_vh_empty_title">No snapshots yet</div>' +
        '<div class="_eli3_vh_empty_desc">Click "📸 New snapshot" above to capture the current state of this document.</div>' +
      '</div>';
  } else {
    versions.forEach(function (v) {
      var node = document.createElement("div");
      node.className = "_eli3_vh_node";
      var isCurrent = v.sessionId === currentSessionId;
      var dateStr = formatTs(v.timestamp);
      var num = v.displayNumber || "?";
      var labelEsc = _esc(v.label || "(unlabeled)");
      var currentBadge = isCurrent
        ? '<span class="_eli3_vh_badge_current">CURRENT</span>'
        : '';
      node.innerHTML =
        '<div class="_eli3_vh_node_head">' +
          '<div class="_eli3_vh_node_main">' +
            '<div class="_eli3_vh_node_title">' +
              '<span class="_eli3_vh_node_num">#' + num + '</span> ' +
              labelEsc + ' ' + currentBadge +
            '</div>' +
            '<div class="_eli3_vh_node_date">' + _esc(dateStr) + '</div>' +
          '</div>' +
          '<button type="button" class="_eli3_vh_del" title="Delete this snapshot">🗑️</button>' +
        '</div>' +
        '<div class="_eli3_vh_node_actions">' +
          '<button type="button" class="_eli3_vh_view">👁 View</button>' +
          '<button type="button" class="_eli3_vh_compare">↔ Compare</button>' +
        '</div>';
      node.querySelector("._eli3_vh_del").onclick = function () { _confirmDelete(v, onDelete); };
      node.querySelector("._eli3_vh_view").onclick = function () { onView(v); };
      node.querySelector("._eli3_vh_compare").onclick = function () { onCompare(v); };
      listEl.appendChild(node);
    });
  }

  mount.appendChild(root);
  return {
    refresh: function (newVersions) {
      versions = (newVersions || []).slice();
      // Re-render by recursing.
      renderTimeline({
        mount: mount, versions: versions, currentSessionId: currentSessionId,
        onDelete: onDelete, onView: onView,
        onCompare: onCompare, onBack: onBack, formatTs: formatTs,
      });
    },
  };
}

view._confirmDelete:
function _confirmDelete(v, onDelete) {
  if (typeof showEliDialog !== "function") { onDelete(v); return; }
  var ov;
  ov = showEliDialog({
    variant: "danger",
    icon: "🗑️",
    title: "Delete Version #" + (v.displayNumber || "?") + "?",
    body: "This permanently removes the snapshot from this document.",
    primary: {
      label: "Delete",
      onclick: function () {
        if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
        onDelete(v);
      },
    },
    secondary: { label: "Cancel" },
  });
}

// FROM v2 showPreviewModal (22476). Floating preview window with the
// snapshot's HTML inside an iframe.

view.renderPreviewModal:
function renderPreviewModal(opts) {
  var title = String(opts.title || "Preview");
  var html = String(opts.html || "");
  var existing = document.getElementById("_eli3_vh_preview");
  if (existing) existing.remove();
  var modal = document.createElement("div");
  modal.id = "_eli3_vh_preview";
  modal.className = "_eli3_vh_preview_modal";
  modal.innerHTML =
    '<div class="_eli3_vh_preview_header">' +
      '<div class="_eli3_vh_preview_title">👁 ' +
        String(title).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;") +
      '</div>' +
      '<button type="button" class="_eli3_vh_preview_close">✕</button>' +
    '</div>' +
    '<iframe class="_eli3_vh_preview_frame"></iframe>';
  document.body.appendChild(modal);
  var iframe = modal.querySelector("._eli3_vh_preview_frame");
  var doc = iframe.contentWindow.document;
  doc.open();
  doc.write(
    '<html><head><style>' +
      'body { font-family: "Segoe UI", sans-serif; padding: 25px; background: white; color: #333; line-height: 1.5; margin:0; }' +
      'table { border-collapse: collapse; width: 100%; }' +
      'td, th { border: 1px solid #ccc; padding: 5px; }' +
      'h1, h2, h3 { color: #1565c0; margin-top: 0; }' +
      'pre { background: #f5f5f5; padding: 10px; border: 1px solid #ddd; overflow-x: auto; }' +
    '</style></head><body>' + html + '</body></html>'
  );
  doc.close();
  // Document-level listeners stashed into refs so close() can remove
  // them — otherwise mousemove/mouseup leak into every subsequent modal
  // open (closed-over `modal` and `dragging` from prior cycles linger).
  var header = modal.querySelector("._eli3_vh_preview_header");
  var dragging = false, sx = 0, sy = 0, sl = 0, st = 0;
  function _onHeaderDown(e) {
    if (e.target.className === "_eli3_vh_preview_close") return;
    dragging = true; sx = e.clientX; sy = e.clientY;
    sl = modal.offsetLeft; st = modal.offsetTop;
    e.preventDefault();
  }
  function _onMove(e) {
    if (!dragging) return;
    modal.style.left = (sl + e.clientX - sx) + "px";
    modal.style.top = (st + e.clientY - sy) + "px";
  }
  function _onUp() { dragging = false; }
  header.addEventListener("mousedown", _onHeaderDown);
  document.addEventListener("mousemove", _onMove);
  document.addEventListener("mouseup", _onUp);
  function _close() {
    try { document.removeEventListener("mousemove", _onMove); } catch (e) {}
    try { document.removeEventListener("mouseup", _onUp); } catch (e) {}
    if (modal.parentNode) modal.remove();
  }
  modal.querySelector("._eli3_vh_preview_close").onclick = _close;
  return { close: _close };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["version_history"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var analyze            = efns.analyze;
  var buildSnapshotEntry = efns.buildSnapshotEntry;
  var pruneHistory       = efns.pruneHistory;
  var formatTs           = efns.formatTs;
  var renderTimeline     = vfns.renderTimeline;
  var renderPreviewModal = vfns.renderPreviewModal;
  if (!analyze || !buildSnapshotEntry || !renderTimeline) {
    eli.log.event("tool", "version_history_load_failed", {
      hasAnalyze: !!analyze, hasBuild: !!buildSnapshotEntry, hasView: !!renderTimeline,
    });
    return;
  }

  // Per-session id — used to mark "CURRENT" badge in the timeline. Same
  // shape as v2 line 1453.
  var SESSION_ID = "sess_" + Date.now();

  // ─── Office settings I/O ─────────────────────────────────────────
  // FROM v2 getHistoryFromDoc (line 22433) + saveHistoryToDoc (22448).
  function _readHistory() {
    return new Promise(function (resolve) {
      try {
        var raw = Office.context.document.settings.get("eli_version_history");
        if (!raw) { resolve([]); return; }
        var data = typeof raw === "string" ? JSON.parse(raw) : raw;
        resolve(Array.isArray(data) ? data : []);
      } catch (e) {
        eli.log.event("tool", "version_history_read_failed", { msg: e && e.message });
        resolve([]);
      }
    });
  }
  function _writeHistory(history) {
    return new Promise(function (resolve) {
      try {
        // Engine clones + adds displayNumber; we strip that here defensively
        // (legacy entries persisted before the engine clone fix may carry it).
        var pruned = pruneHistory(history, 5).map(function (h) {
          var clean = {};
          Object.keys(h).forEach(function (k) {
            if (k !== "displayNumber") clean[k] = h[k];
          });
          return clean;
        });
        // Office settings has a historical ~2MB-per-document cap. 5 entries
        // x 250KB worst case = 1.25MB, comfortable. Above 1.5MB serialized
        // we proactively trim to 3 entries to leave headroom for other
        // tools' settings (EliEmailerPrefill, AgreementDataDetails, etc.).
        var serialized = JSON.stringify(pruned);
        if (serialized.length > 1.5 * 1024 * 1024 && pruned.length > 3) {
          pruned = pruned.slice(pruned.length - 3);
          serialized = JSON.stringify(pruned);
          eli.log.event("tool", "version_history_quota_trim", {
            kept: pruned.length, sizeBytes: serialized.length,
          });
        }
        Office.context.document.settings.set("eli_version_history", serialized);
        Office.context.document.settings.saveAsync(function (res) {
          if (res && res.status !== Office.AsyncResultStatus.Succeeded) {
            eli.log.event("tool", "version_history_save_failed", {
              msg: res.error && res.error.message,
              code: res.error && res.error.code,
              sizeBytes: serialized.length,
            });
            if (typeof showToast === "function") {
              var hint = serialized.length > 1.5 * 1024 * 1024
                ? "snapshot too large — try removing older versions"
                : (res.error && res.error.message) || "saveAsync failed";
              showToast("Snapshot save failed: " + hint, "err");
            }
            resolve(false);
            return;
          }
          resolve(true);
        });
      } catch (e) {
        eli.log.event("tool", "version_history_write_failed", { msg: e && e.message });
        if (typeof showToast === "function") {
          showToast("Snapshot write failed: " + (e && e.message), "err");
        }
        resolve(false);
      }
    });
  }

  // ─── Snapshot capture (Word.run) ─────────────────────────────────
  // FROM v2 createSnapshot lines 22378-22387. Originally loaded HTML +
  // OOXML in a single runRaw scope — but on a 50pp+ doc that breaches
  // the 100ms `Word.run` keystone budget, since OOXML is the heaviest
  // call Word.js exposes.
  //
  // Two-pass approach: read HTML first (cheaper), then read OOXML in a
  // separate runRaw IF the HTML is under 1MB. On big docs, OOXML is
  // skipped and snapshot drops back to html-only — Compare can still
  // diff the deterministicBlocks (text-only); it just loses the
  // redline-state-transition signal that OOXML's <w:ins>/<w:del> tags
  // carry. Acceptable trade-off: huge docs are rare; budget is keystone.
  var OOXML_HTML_BUDGET = 1024 * 1024; // 1 MB
  function _captureCurrentDoc() {
    var captured = { html: "", ooxml: "" };
    return eli.host.runRaw("version_history:capture_html", function (context) {
      var htmlReq = context.document.body.getHtml();
      return context.sync().then(function () { return htmlReq.value || ""; });
    }).then(function (html) {
      captured.html = String(html || "");
      if (captured.html.length > OOXML_HTML_BUDGET) {
        eli.log.event("tool", "version_history_capture_skip_ooxml", {
          htmlLen: captured.html.length, budget: OOXML_HTML_BUDGET,
        });
        return captured;
      }
      return eli.host.runRaw("version_history:capture_ooxml", function (context) {
        var ooxmlReq = context.document.body.getOoxml();
        return context.sync().then(function () { return ooxmlReq.value || ""; });
      }).then(function (ooxml) {
        captured.ooxml = String(ooxml || "");
        return captured;
      }).catch(function (err) {
        eli.log.event("tool", "version_history_capture_ooxml_failed", { msg: err && err.message });
        return captured; // html-only is still useful
      });
    }).catch(function (err) {
      eli.log.event("tool", "version_history_capture_failed", { msg: err && err.message });
      return null;
    });
  }

  // ─── Public createSnapshot for other tools (build_draft post-save) ─
  // Save panel calls eli.dispatch("version_history", "snapshot", {label})
  // after writing the .docx. v3-equivalent of v2 createSnapshot.
  function createSnapshot(payload) {
    payload = payload || {};
    var label = payload.label || "Auto-Save";
    return _captureCurrentDoc().then(function (raw) {
      if (!raw) return false;
      var entry = buildSnapshotEntry({
        sessionId: SESSION_ID,
        timestamp: Date.now(),
        label: label,
        author: payload.author || "Me",
        html: raw.html,
        ooxml: raw.ooxml,
      });
      return _readHistory().then(function (history) {
        // Dedup by sessionId — replaces existing same-session entry
        // unless forceNew. Matches v2 line 22417.
        var idx = history.findIndex(function (v) { return v.sessionId === SESSION_ID; });
        if (idx !== -1 && !payload.forceNew) history[idx] = entry;
        else history.push(entry);
        return _writeHistory(history).then(function () {
          if (eli.activity && eli.activity.add) {
            eli.activity.add({
              type: "version-history",
              icon: "📷",
              label: "Version History · Snapshot",
              summary: "Captured: " + label,
              payload: { label: label, sessionId: SESSION_ID },
              provenance: { timestamp: Date.now() },
            });
          }
          return true;
        });
      });
    });
  }

  // ─── Open the timeline ───────────────────────────────────────────
  // The timeline renders the list of snapshots + delete/view/compare
  // actions. Capture happens from the kernel footer's 📷 button, which
  // calls createSnapshot directly. When a snapshot lands while the
  // timeline is open, the bus subscription below refreshes the list.
  var _activeUi = null; // current timeline UI, if open
  var _activeBusUnsub = null;
  function _open() {
    eli.log.event("tool", "version_history_open_called", {});
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) {
      eli.log.event("tool", "version_history_open_no_mount", {});
      if (typeof showToast === "function") {
        showToast("Dashboard root missing — try reopening ELI", "err");
      }
      return;
    }
    // FSM transition is best-effort — never gate the open on it. The
    // previous version tried `idle → rendering` (illegal) and threw,
    // which the catch swallowed but the FSM consumers downstream got
    // confused. Now we attempt a safe transition only when in idle and
    // tolerate every other state silently.
    try {
      var cur = eli.fsm.getCurrent ? eli.fsm.getCurrent() : null;
      if (cur === "idle") eli.fsm.transition("scanning");
    } catch (e) { /* tolerate */ }
    _readHistory().then(function (history) {
      return analyze({ history: history }, {});
    }).then(function (result) {
      _activeUi = renderTimeline({
        mount: mount,
        versions: result.history,
        currentSessionId: SESSION_ID,
        formatTs: formatTs,
        onBack: function () {
          // Tear down bus subscription before navigating away.
          try { if (typeof _activeBusUnsub === "function") _activeBusUnsub(); } catch (e) {}
          _activeBusUnsub = null;
          _activeUi = null;
          try { eli.fsm.transition("idle"); } catch (e) {}
          if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
          else if (eli.dashboard && typeof eli.dashboard.render === "function") eli.dashboard.render();
        },
        onDelete: eli.events.guard(function (v) {
          return _readHistory().then(function (h) {
            var filtered = h.filter(function (x) { return x.timestamp !== v.timestamp; });
            return _writeHistory(filtered).then(function () {
              if (typeof showToast === "function") showToast("🗑️ Deleted", "ok");
              return analyze({ history: filtered }, {});
            }).then(function (r) {
              if (_activeUi) _activeUi.refresh(r.history);
            });
          });
        }, "version_history.delete"),
        onView: function (v) {
          if (renderPreviewModal && v.html) {
            renderPreviewModal({ title: "Snapshot: " + (v.label || ""), html: v.html });
          } else if (renderPreviewModal && v.bodyOoxml) {
            var preview = String(v.bodyOoxml).replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
            renderPreviewModal({
              title: "Snapshot: " + (v.label || ""),
              html: '<pre style="white-space:pre-wrap;font-family:monospace;">' +
                preview.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;") + '</pre>',
            });
          } else if (typeof showToast === "function") {
            showToast("No preview available for this snapshot", "warn");
          }
        },
        onCompare: function (v) {
          // 2026-05-12: route directly to compare.versionCompare (the
          // ported v2 runVersionCompare path). v2 called runVersionCompare(v)
          // directly; v3 compare tool advertises this as compare/versionCompare.
          // compare is demand-tier now, so eval it first via ensureLoaded.
          var ensureP = (eli.tools && typeof eli.tools.ensureLoaded === "function")
            ? eli.tools.ensureLoaded("compare")
            : Promise.resolve(true);
          ensureP.then(function () {
            var dispatched = false;
            try {
              if (eli.get && typeof eli.get("compare", "versionCompare") === "function") {
                eli.dispatch("compare", "versionCompare", v);
                dispatched = true;
              } else if (typeof window.runVersionCompare === "function") {
                window.runVersionCompare(v);
                dispatched = true;
              } else if (eli.get && typeof eli.get("tile", "app_compare") === "function") {
                eli.dispatch("tile", "app_compare");
                dispatched = true;
                if (typeof showToast === "function") {
                  showToast("Opened Compare — select the historical snapshot manually.", "info");
                }
              }
            } catch (e) {
              eli.log.event("tool", "version_history_compare_dispatch_failed", { msg: e && e.message });
            }
            if (!dispatched && typeof showToast === "function") {
              showToast("Compare tool not installed — open Tool Manager to install.", "warn");
            }
          });
        },
      });

      // Wire bus refresh — when the kernel footer camera (or a build_draft
      // post-save) appends a new snapshot, refresh the timeline list in
      // place so the user sees the new entry without re-opening the tool.
      if (eli.bus && typeof eli.bus.on === "function") {
        try { if (typeof _activeBusUnsub === "function") _activeBusUnsub(); } catch (e) {}
        _activeBusUnsub = eli.bus.on("activity:added", function (entry) {
          if (!entry || entry.type !== "version-history") return;
          if (!_activeUi) return;
          _readHistory().then(function (h) {
            return analyze({ history: h }, {});
          }).then(function (r) {
            if (_activeUi) _activeUi.refresh(r.history);
          }).catch(function () { /* tolerate */ });
        });
      }
    }).catch(function (err) {
      eli.log.event("tool", "version_history_open_failed", { msg: err && err.message });
      if (typeof showToast === "function") {
        showToast("Version History failed: " + (err && err.message || "unknown"), "err");
      }
    });
  }

  // ─── Footer slot — camera + version pill ─────────────────────────
  // Tool-owned (was kernel _populateStatus + _refreshVersionFooterSlot
  // until Batch 1C). The kernel exposes a generic footer slot host;
  // we register a builder, the kernel calls it each time the status
  // bar re-paints. Builder is idempotent — reads current history,
  // paints the latest label, wires the click + camera buttons.
  //
  // Two robustness measures retained from the v2-era kernel impl:
  //  1. Generation counter — overlapping listHistory calls (tool:loaded
  //     + offline-transition close together) shouldn't clobber each
  //     other's DOM updates.
  //  2. 5s in-memory cache — _refreshStatus runs on every FSM /
  //     online/offline transition; cache avoids spamming IDB reads.
  //     Busted on snapshot-add via activity:added bus.
  var _footerCache = null;
  var _FOOTER_TTL = 5000;
  var _footerGen = 0;
  function _renderFooterPill(mount) {
    var verGroup = document.createElement("span");
    verGroup.className = "_eli3_status_section _eli3_status_vergroup";
    verGroup.id = "_eli3_status_vergroup";
    var cam = document.createElement("button");
    cam.type = "button";
    cam.className = "_eli3_status_camera";
    cam.id = "_eli3_status_camera";
    cam.textContent = "📷";
    cam.title = "Take a snapshot of this document";
    cam.onclick = function (e) {
      e.preventDefault(); e.stopPropagation();
      _captureFooterSnapshot(cam);
    };
    verGroup.appendChild(cam);
    var ver = document.createElement("span");
    ver.className = "_eli3_status_version _eli3_status_version_active";
    ver.id = "_eli3_status_version";
    ver.textContent = "📷 Versions";
    ver.title = "Open Version History";
    ver.style.cursor = "pointer";
    ver.onclick = function (ev) {
      ev.preventDefault(); ev.stopPropagation();
      _open();
    };
    verGroup.appendChild(ver);
    mount.appendChild(verGroup);

    var myGen = ++_footerGen;
    function _paint(history) {
      if (myGen !== _footerGen) return;
      if (!Array.isArray(history) || !history.length) {
        ver.textContent = "No versions";
        ver.title = "Click 📷 to capture the first snapshot · Click here to open Version History";
        return;
      }
      var latest = history.slice().sort(function (a, b) {
        return (b.timestamp || 0) - (a.timestamp || 0);
      })[0];
      var lbl = String(latest.label || "Snapshot");
      ver.textContent = lbl.length > 26 ? (lbl.substring(0, 24) + "…") : lbl;
      ver.title = "Latest version: " + lbl + " · Click to open Version History";
    }
    if (_footerCache && (Date.now() - _footerCache.ts) < _FOOTER_TTL) {
      _paint(_footerCache.history);
      return;
    }
    _readHistory().then(function (history) {
      _footerCache = { ts: Date.now(), history: history };
      _paint(history);
    }).catch(function () { /* tolerate — default label remains */ });
  }

  // Camera click — snapshot now, log + bust cache + refresh footer.
  // Verbose logging retained because the kernel-era version silently
  // swallowed failures (Promise.resolve wrapping, runRaw errors) and
  // the user saw "click does nothing" with no diagnostic.
  function _captureFooterSnapshot(btn) {
    eli.log.event("version_history", "camera_clicked", {});
    function _pad2(n) { return (n < 10 ? "0" : "") + n; }
    var origText = btn.textContent;
    btn.disabled = true; btn.textContent = "…";
    var stamp = new Date();
    var label = "Snapshot " +
      (stamp.getMonth() + 1) + "/" + stamp.getDate() + " " +
      _pad2(stamp.getHours()) + ":" + _pad2(stamp.getMinutes());
    var p;
    try {
      p = createSnapshot({ label: label, forceNew: true });
    } catch (err) {
      btn.disabled = false; btn.textContent = origText;
      eli.log.event("version_history", "camera_snapshot_threw", { msg: err && err.message });
      if (typeof showToast === "function") {
        showToast("Snapshot failed: " + (err && err.message || "unknown"), "err");
      }
      return;
    }
    Promise.resolve(p).then(function (ok) {
      btn.disabled = false; btn.textContent = origText;
      eli.log.event("version_history", "camera_snapshot_done", { ok: !!ok });
      if (ok) {
        if (typeof showToast === "function") showToast("📷 Saved: " + label, "ok");
        _footerCache = null;
        if (eli.dashboard && typeof eli.dashboard.refreshFooter === "function") {
          eli.dashboard.refreshFooter();
        }
      } else {
        if (typeof showToast === "function") showToast("Snapshot returned no result — check console", "warn");
      }
    }).catch(function (err) {
      btn.disabled = false; btn.textContent = origText;
      eli.log.event("version_history", "camera_snapshot_failed", { msg: err && err.message });
      if (typeof showToast === "function") {
        showToast("Snapshot failed: " + (err && err.message || "unknown"), "err");
      }
    });
  }

  eli.register({
    tile: { app_version_history: function () {
      try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedVersionHistory"); } catch (e) {}
      _open();
    } },
    // Programmatic snapshot — used by build_draft post-save.
    version_history: { snapshot: createSnapshot },
  });

  // Register the footer pill via kernel slot API. Order 50 — right
  // edge of the status bar, replacing what was kernel-hardcoded.
  if (eli.dashboard && typeof eli.dashboard.registerFooterSlot === "function") {
    eli.dashboard.registerFooterSlot("version_history", function (opts) {
      _renderFooterPill(opts.mount);
    }, { region: "right", order: 50 });
  }

  // Bus refresh — when a snapshot lands (from anywhere — footer
  // camera, build_draft post-save dispatch), bust cache + repaint
  // the footer so the pill shows the new latest label.
  if (eli.bus && typeof eli.bus.on === "function") {
    eli.bus.on("activity:added", function (entry) {
      if (!entry || entry.type !== "version-history") return;
      _footerCache = null;
      if (eli.dashboard && typeof eli.dashboard.refreshFooter === "function") {
        eli.dashboard.refreshFooter();
      }
    });
  }

  // Expose for kernel footer consumption + v2-shim callers. The kernel
  // footer pill calls `openTimeline` directly (bypasses dispatch registry
  // for reliability) and the camera button calls `createSnapshot`.
  window.eli.versionHistory = {
    createSnapshot: createSnapshot,
    listHistory: _readHistory,
    openTimeline: _open,
    sessionId: SESSION_ID,
  };

  eli.log.event("tool", "version_history_initialized", {});
}

jsonTools.css:
/* version_history tool styles. Injected as <style data-tool="version_history">. */

/* Reuses _eli3_ae_root + _eli3_ae_bar + _eli3_ae_back + _eli3_ae_title
   from auto_emailer for header consistency (dark navy + gold). */

._eli3_vh_root {
  display: flex; flex-direction: column;
  width: 100%; height: 100%;
  background: #fff;
  overflow: hidden;
}
._eli3_vh_capture_btn {
  flex: 0 0 auto;
  background: rgba(255,255,255,0.10);
  border: 1px solid rgba(255,255,255,0.20);
  color: #f2d866;
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  padding: 6px 12px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_vh_capture_btn:hover:not(:disabled) {
  background: rgba(201,162,39,0.25);
  border-color: rgba(201,162,39,0.6);
  transform: translateY(-1px);
}
._eli3_vh_capture_btn:disabled { opacity: 0.6; cursor: progress; }

._eli3_vh_intro {
  flex: 0 0 auto;
  padding: 10px 14px;
  background: linear-gradient(180deg, #eff6ff 0%, #dbeafe 100%);
  border-bottom: 1px solid #93c5fd;
  font: 500 11px/1.5 'Inter', sans-serif;
  color: #1e40af;
}

._eli3_vh_list {
  flex: 1 1 auto;
  overflow-y: auto;
  min-height: 0;
  padding: 12px 14px;
  display: flex; flex-direction: column; gap: 8px;
}

/* Empty state */
._eli3_vh_empty {
  text-align: center;
  padding: 40px 20px;
  color: #64748b;
}
._eli3_vh_empty_icon {
  font-size: 38px;
  margin-bottom: 10px;
}
._eli3_vh_empty_title {
  font: 700 14px/1.2 'Inter', sans-serif;
  color: #0f172a;
  margin-bottom: 6px;
}
._eli3_vh_empty_desc {
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #64748b;
  max-width: 360px;
  margin: 0 auto;
}

/* Timeline node */
._eli3_vh_node {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #1565c0;
  padding: 10px 12px;
  display: flex; flex-direction: column;
  gap: 8px;
  transition: border-color 0.15s, box-shadow 0.15s;
}
._eli3_vh_node:hover {
  border-color: #cbd5e1;
  border-left-color: #0d47a1;
  box-shadow: 0 2px 6px rgba(15, 23, 42, 0.06);
}
._eli3_vh_node_head {
  display: flex; justify-content: space-between; align-items: flex-start;
  gap: 8px;
}
._eli3_vh_node_main { flex: 1; min-width: 0; }
._eli3_vh_node_title {
  font: 800 12px/1.3 'Inter', sans-serif;
  color: #1565c0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
._eli3_vh_node_num {
  color: #64748b;
  margin-right: 4px;
}
._eli3_vh_node_date {
  font: 500 10px/1.3 'JetBrains Mono', monospace;
  color: #94a3b8;
  margin-top: 3px;
}
._eli3_vh_badge_current {
  display: inline-block;
  background: #e3f2fd;
  color: #1565c0;
  font: 800 9px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  padding: 3px 6px;
  margin-left: 6px;
  vertical-align: 1px;
  border: 1px solid #93c5fd;
}
._eli3_vh_del {
  flex: 0 0 auto;
  background: transparent;
  border: none;
  cursor: pointer;
  font-size: 14px;
  padding: 4px 8px;
  color: #64748b;
  transition: color 0.15s;
}
._eli3_vh_del:hover { color: #c62828; }

._eli3_vh_node_actions {
  display: flex; gap: 6px;
}
._eli3_vh_node_actions button {
  flex: 1;
  padding: 6px 10px;
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_vh_view {
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  color: #475569;
}
._eli3_vh_view:hover {
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  color: #0f172a;
  border-color: #94a3b8;
}
._eli3_vh_compare {
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  box-shadow: 0 1px 3px rgba(21, 101, 192, 0.25);
}
._eli3_vh_compare:hover {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%);
  transform: translateY(-1px);
  box-shadow: 0 3px 8px rgba(21, 101, 192, 0.35);
}

/* Capture-label dialog choices */
._eli3_vh_choice_grid {
  display: flex; flex-direction: column;
  gap: 6px;
  margin: 8px 0;
}
._eli3_vh_choice {
  text-align: left;
  padding: 10px 12px;
  font: 700 12px/1.3 'Inter', sans-serif;
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  color: #0f172a;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_vh_choice:hover {
  background: linear-gradient(180deg, #fff 0%, #e3f2fd 100%);
  border-color: #1565c0;
  color: #0d47a1;
}

/* Preview modal */
._eli3_vh_preview_modal {
  position: fixed;
  top: 60px; left: 30px;
  width: 500px; height: 600px;
  background: #fff;
  display: flex; flex-direction: column;
  box-shadow: 0 15px 50px rgba(0, 0, 0, 0.3);
  border: 1px solid #455a64;
  z-index: 99999;
  resize: both;
  overflow: hidden;
  min-width: 300px;
  min-height: 200px;
}
._eli3_vh_preview_header {
  flex: 0 0 auto;
  padding: 10px 15px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fff;
  display: flex; justify-content: space-between; align-items: center;
  border-bottom: 3px solid #c9a227;
  cursor: move;
  user-select: none;
}
._eli3_vh_preview_title {
  font: 700 12px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  pointer-events: none;
}
._eli3_vh_preview_close {
  background: none;
  border: none;
  color: #cbd5e1;
  font-size: 16px;
  cursor: pointer;
  font-weight: 700;
  padding: 0 4px;
}
._eli3_vh_preview_close:hover { color: #f2d866; }
._eli3_vh_preview_frame {
  flex: 1 1 auto;
  border: none;
  width: 100%;
  background: #f5f5f5;
}

/* ─── Footer slot occupants (moved from taskpane_v3.css 1856-1898 + 1938-1946 in Batch 5B 2026-05-11) ───
 * The status-bar version pill + camera button are version_history-only
 * decorations. Kernel still owns the inactive default `.status-version,
 * ._eli3_status_version` rule (string-only paint when this tool isn't
 * loaded) plus the `_eli3_status_bar > ._eli3_status_vergroup` grid-
 * positioning rule. Cosmetics (active gold pill, hover, light-mode) live
 * here and ship with the bundle. */

/* When version_history is installed, the slot becomes a clickable pill
   showing the latest snapshot label. Gold accent indicates "live data". */
._eli3_status_version_active {
  font-family: 'Inter', sans-serif;
  font-size: 10px;
  font-weight: 700;
  color: #c9a227;
  cursor: pointer;
  padding: 3px 8px;
  border: 1px solid rgba(201, 162, 39, 0.4);
  background: rgba(201, 162, 39, 0.08);
}
._eli3_status_version_active:hover {
  color: #f2d866;
  background: rgba(201, 162, 39, 0.18);
  border-color: rgba(201, 162, 39, 0.7);
  transform: translateY(-1px);
}
/* Footer camera button — borderless, sits next to the version pill.
   Clicking takes a snapshot via window.eli.versionHistory.createSnapshot.
   Hidden until version_history is loaded (kernel toggles `hidden`). */
._eli3_status_vergroup {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
._eli3_status_camera {
  background: transparent;
  border: 0;
  padding: 2px 4px;
  font-size: 14px;
  cursor: pointer;
  opacity: 0.75;
  transition: opacity 0.15s, transform 0.12s;
  line-height: 1;
}
._eli3_status_camera:hover {
  opacity: 1;
  transform: scale(1.15);
}
._eli3_status_camera:disabled {
  opacity: 0.4;
  cursor: wait;
}
body.beta-ui-active.light-mode ._eli3_status_version_active {
  color: #92400e;
  border-color: rgba(180, 83, 9, 0.4);
  background: rgba(254, 243, 199, 0.6);
}
body.beta-ui-active.light-mode ._eli3_status_version_active:hover {
  color: #78350f;
  background: rgba(253, 230, 138, 0.8);
}
